
local my=[==[]==]
local mjfv=
(function(...)
local agns={22,162,90,61,87,210,97,149,35,253,58,144,220,40,168,226,98,175,182,217,172,203,32,220,122,116,207,184}
local ricd=bit32 or bit
local otq=ricd.bxor
for hxqp=1,#agns do agns[hxqp]=otq(agns[hxqp],(163*hxqp+154)%256) end
local oiw="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local bc={}
for hhlgm=1,#oiw do bc[oiw:byte(hhlgm)]=hhlgm-1 end
local function phpja(str)
  local R={} local acc,nb=0,0
  for km=1,#str do
    local v=bc[str:byte(km)]
    if v then
      acc=acc*64+v; nb=nb+6
      if nb>=8 then nb=nb-8; R[#R+1]=math.floor(acc/2^nb)%256; acc=acc%2^nb end
    end
  end
  return R
end
local function np(key,data)
  local S={} for dl=0,255 do S[dl]=dl end
  local j=0
  for hgf=0,255 do
    j=(j+S[hgf]+key[(hgf%#key)+1])%256
    S[hgf],S[j]=S[j],S[hgf]
  end
  local O={} local ii=0; j=0
  for n=1,#data do
    ii=(ii+1)%256; j=(j+S[ii])%256; S[ii],S[j]=S[j],S[ii]
    O[n]=string.char(otq(data[n],S[(S[ii]+S[j])%256]))
  end
  return table.concat(O)
end
local code=np(agns,phpja(""))
local nf,ne=(loadstring or load)("return "..code)
if not nf then error(ne or "rage quit chain error") end
local vi=nf()
return function(big) return vi(big) end
end)(...)

return mjfv(my)
